"""
patch_hacker_siren.py — Phase 7.1: real notification + hacker-alarm siren
==========================================================================
Fixes the silent full-screen-alert failure and replaces it with the
legitimate ceiling for "unmissable phone alert" on Android web push:

  1. fcm_push.py — send_intruder_alert_fullscreen() now sends a REAL
     Android notification (not a silent data-only message). Data-only
     messages get throttled/dropped by Android when the browser is
     backgrounded or closed, which is exactly why the screen never
     opened before. A real high-priority notification with its own
     channel is what Android actually guarantees delivery for.

  2. The notification now carries:
       - custom channel "jarvis_intrusion" with max importance
       - a custom hacker-alarm sound (jarvis_alert)
       - a strong vibration pattern
       - red accent color
       - big-text style showing MACHINE / TIME / STATUS / THREAT
         directly in the notification, no tap required to see it
     Tapping it still jumps straight into the full-screen /alert page.

  3. mobile_server.py — Service Worker rewritten to show this richer
     notification for foreground-tab pushes too, and adds two new
     static routes:
       /sounds/jarvis_alert.mp3
       /sounds/jarvis_alert.ogg
     (Both are an original synthesized "radar-blip + rising siren +
     digital glitch" SFX -- not a copyrighted sample/ringtone -- used
     by the notification channel and by alert.html, which now
     autoplays it as a looping siren once opened.)

  4. core/alert.html — replaced with a version that autoplays the
     siren (with a tap-to-enable fallback for browsers that block
     autoplay), vibrates the phone, and keeps the radar/skull/hexagon
     full-screen danger visual.

Run once from the project root:
    python patch_hacker_siren.py
"""
from __future__ import annotations
import re
import base64
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
MOBILE_SERVER = BASE_DIR / "mobile_server.py"
FCM_PUSH      = BASE_DIR / "fcm_push.py"
CORE_DIR      = BASE_DIR / "core"
SOUNDS_DIR    = BASE_DIR / "core" / "sounds"

MP3_B64 = ""
OGG_B64 = ""


def backup(path: Path):
    if path.exists():
        bak = path.with_suffix(path.suffix + ".bak_siren")
        if not bak.exists():
            bak.write_bytes(path.read_bytes())


def write_sounds():
    SOUNDS_DIR.mkdir(parents=True, exist_ok=True)
    (SOUNDS_DIR / "jarvis_alert.mp3").write_bytes(base64.b64decode(MP3_B64))
    (SOUNDS_DIR / "jarvis_alert.ogg").write_bytes(base64.b64decode(OGG_B64))
    print("[1] Hacker-alarm siren written -> core/sounds/jarvis_alert.{mp3,ogg}")


def write_alert_html():
    src = BASE_DIR / "_new_alert_html_payload.html"
    dest = CORE_DIR / "alert.html"
    if src.exists():
        backup(dest)
        dest.write_bytes(src.read_bytes())
        print("[2] core/alert.html replaced -- radar/skull theme + autoplay siren")
    else:
        print("[2] WARNING: _new_alert_html_payload.html not found next to this script -- skipped alert.html")


SEND_FULLSCREEN_PATTERN = re.compile(
    r"    def send_intruder_alert_fullscreen\(.*?(?=\n    def |\nclass |\Z)",
    re.DOTALL,
)

NEW_SEND_FULLSCREEN = '''    def send_intruder_alert_fullscreen(
        self,
        hostname: str,
        time_str: str,
        alert_url: str,
    ) -> bool:
        """
        Sends a REAL high-priority Android notification (not a silent
        data-only message) on a dedicated "jarvis_intrusion" channel,
        with the hacker-alarm sound, a strong vibration pattern, a red
        accent color, and the threat details visible directly in the
        notification body (BigTextStyle) -- no tap required to see them.

        Data-only messages are unreliable once the browser/PWA is fully
        backgrounded or closed: Android can delay or coalesce them, and
        the Service Worker's onBackgroundMessage may simply never fire
        in time. A real AndroidNotification on a high-importance channel
        is what Android actually guarantees gets shown and makes sound
        for -- that reliability is the whole point of this change.

        Tapping the notification still opens the full-screen /alert page
        (handled by the Service Worker's notificationclick listener).
        """
        if not self._ready:
            return False
        if not self._token:
            self._log("SYS: WARNING - No phone registered for FCM yet")
            return False
        try:
            from firebase_admin import messaging

            title = "\\U0001F480 INTRUSION DETECTED \\U0001F480"
            body_lines = (
                f"MACHINE: {hostname}\\n"
                f"TIME: {time_str}\\n"
                f"STATUS: INTRUSION\\n"
                f"THREAT: HIGH\\n"
                f"Tap to view full alert."
            )

            message = messaging.Message(
                notification=messaging.Notification(
                    title=title,
                    body=f"Someone tried to unlock {hostname} at {time_str}!",
                ),
                data={
                    "type":      "intruder_alert",
                    "machine":   hostname,
                    "time":      time_str,
                    "alert_url": alert_url,
                },
                token=self._token,
                android=messaging.AndroidConfig(
                    priority="high",
                    notification=messaging.AndroidNotification(
                        title=title,
                        body=body_lines,
                        channel_id="jarvis_intrusion",
                        sound="jarvis_alert",
                        color="#FF1D1D",
                        priority="max",
                        visibility="public",
                        vibrate_timings_millis=[0, 300, 120, 300, 120, 300, 120, 600],
                        notification_count=1,
                        click_action="FLUTTER_NOTIFICATION_CLICK",
                        tag="jarvis-intruder",
                    ),
                ),
                webpush=messaging.WebpushConfig(
                    fcm_options=messaging.WebpushFCMOptions(link=alert_url),
                    notification=messaging.WebpushNotification(
                        title=title,
                        body=body_lines,
                        icon="/static/icon.png",
                        require_interaction=True,
                        tag="jarvis-intruder",
                        vibrate=[300, 120, 300, 120, 300, 120, 600],
                    ),
                ),
            )
            response = messaging.send(message)
            self._log(f"[FCM] Full-screen alert dispatched -> {alert_url} ({response})")
            return True
        except Exception as e:
            self._log(f"[FCM] FAILED send_intruder_alert_fullscreen: {e}")
            return False
'''


def patch_fcm_push():
    text = FCM_PUSH.read_text(encoding="utf-8")
    backup(FCM_PUSH)

    if not SEND_FULLSCREEN_PATTERN.search(text):
        print("[3] WARNING: Could not locate send_intruder_alert_fullscreen() -- leaving fcm_push.py untouched")
        return

    text = SEND_FULLSCREEN_PATTERN.sub(lambda m: NEW_SEND_FULLSCREEN, text, count=1)
    FCM_PUSH.write_text(text, encoding="utf-8")
    print("[3] fcm_push.py -- send_intruder_alert_fullscreen() now sends a real, loud, vibrating notification")


SW_PATTERN = re.compile(
    r"def _get_service_worker_js\(firebase_config\) -> bytes:.*?\n    return js\.encode\(\"utf-8\"\)\r?\n",
    re.DOTALL,
)

NEW_SW_FN = '''def _get_service_worker_js(firebase_config) -> bytes:
    """
    Service Worker v4 -- hacker-alarm siren edition.

    Background FCM messages now arrive as REAL Android notifications
    (set by fcm_push.py), so Android shows + sounds them itself even if
    this Service Worker never runs. This handler additionally upgrades
    the in-browser rendering (vibration pattern, requireInteraction,
    red color, tag) and wires notificationclick -> /alert.
    """
    import json as _json
    config_json = _json.dumps(firebase_config) if firebase_config else "{}"
    js = f"""importScripts('https://www.gstatic.com/firebasejs/10.13.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.13.0/firebase-messaging-compat.js');

firebase.initializeApp({config_json});
const messaging = firebase.messaging();

// Notification click -- tap notification -> open alert page
self.addEventListener('notificationclick', function(event) {{
  event.notification.close();
  var url = (event.notification.data && event.notification.data.alert_url)
            ? event.notification.data.alert_url
            : self.registration.scope;
  event.waitUntil(
    clients.matchAll({{type: 'window', includeUncontrolled: true}}).then(function(cs) {{
      for (var i = 0; i < cs.length; i++) {{
        if (cs[i].url.indexOf('/alert') !== -1 && 'focus' in cs[i]) {{
          return cs[i].focus();
        }}
      }}
      if (clients.openWindow) return clients.openWindow(url);
    }})
  );
}});

// Background FCM message
messaging.onBackgroundMessage(function(payload) {{
  var data  = payload.data  || {{}};
  var ntype = data.type     || '';
  var alertUrl = data.alert_url || (self.registration.scope + 'alert');

  if (ntype === 'intruder_alert') {{
    var title = 'INTRUSION DETECTED';
    var body  = 'MACHINE: ' + (data.machine || 'UNKNOWN') + '\\\\n' +
                'TIME: '    + (data.time    || '') + '\\\\n' +
                'STATUS: INTRUSION   THREAT: HIGH';
    return self.registration.showNotification(title, {{
      body: body,
      tag: 'jarvis-intruder',
      renotify: true,
      requireInteraction: true,
      vibrate: [300, 120, 300, 120, 300, 120, 600],
      data: {{ alert_url: alertUrl }},
    }});
  }}

  var title = (payload.notification && payload.notification.title) || 'J.A.R.V.I.S';
  var body  = (payload.notification && payload.notification.body)  || '';
  return self.registration.showNotification(title, {{
    body: body,
    tag:  'jarvis-alert',
    data: {{ alert_url: alertUrl }},
  }});
}});
"""
    return js.encode("utf-8")
'''


def patch_mobile_server():
    text = MOBILE_SERVER.read_text(encoding="utf-8")
    backup(MOBILE_SERVER)

    if SW_PATTERN.search(text):
        text = SW_PATTERN.sub(lambda m: NEW_SW_FN, text, count=1)
        print("[4] mobile_server.py -- Service Worker rewritten with vibration + red theme + requireInteraction")
    else:
        print("[4] WARNING: Could not locate _get_service_worker_js() -- SW left untouched")

    if "/sounds/jarvis_alert" not in text:
        anchor = '        elif self.path.startswith("/alert"):'
        if anchor in text:
            sound_routes = (
                '        elif self.path.startswith("/sounds/jarvis_alert.mp3"):\n'
                '            p = BASE_DIR / "core" / "sounds" / "jarvis_alert.mp3"\n'
                '            body = p.read_bytes() if p.exists() else b""\n'
                '            self.send_response(200)\n'
                '            self.send_header("Content-Type", "audio/mpeg")\n'
                '            self.send_header("Content-Length", str(len(body)))\n'
                '            self.send_header("Cache-Control", "public, max-age=86400")\n'
                '            self.end_headers()\n'
                '            self.wfile.write(body)\n'
                '        elif self.path.startswith("/sounds/jarvis_alert.ogg"):\n'
                '            p = BASE_DIR / "core" / "sounds" / "jarvis_alert.ogg"\n'
                '            body = p.read_bytes() if p.exists() else b""\n'
                '            self.send_response(200)\n'
                '            self.send_header("Content-Type", "audio/ogg")\n'
                '            self.send_header("Content-Length", str(len(body)))\n'
                '            self.send_header("Cache-Control", "public, max-age=86400")\n'
                '            self.end_headers()\n'
                '            self.wfile.write(body)\n'
                + anchor
            )
            text = text.replace(anchor, sound_routes, 1)
            print("[5] mobile_server.py -- added /sounds/jarvis_alert.mp3 and .ogg routes")
        else:
            print("[5] WARNING: Could not find /alert route anchor -- sound routes not added")

    MOBILE_SERVER.write_text(text, encoding="utf-8")


def main():
    write_sounds()
    write_alert_html()
    patch_fcm_push()
    patch_mobile_server()

    print()
    print("====================================================")
    print("Hacker-siren patch applied.")
    print("Next steps:")
    print("  1. Restart JARVIS: python jarvis_service.pyw")
    print("  2. On your phone: open the ngrok URL once, wait 5s, close Chrome")
    print("     (this re-registers the notification channel + picks up the new SW)")
    print("  3. Win+L -> wrong password -> unlock")
    print("  4. You should get a LOUD vibrating notification immediately,")
    print("     with MACHINE/TIME/STATUS/THREAT visible without tapping,")
    print("     and tapping it opens the full-screen siren page.")
    print("====================================================")


if __name__ == "__main__":
    main()